const schema = [{"@context":"https://schema.org","@type":"Service","name":"Graphical abstract","serviceType":"Research impact service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/research-impact/graphical-abstract/","description":"Journal-compliant graphical abstracts drawn by scientific illustrators. One image that carries the finding. Elsevier, Springer, Nature, IOPscience and ACS.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Why is my journal asking for one?","acceptedAnswer":{"@type":"Answer","text":"Because it is what appears in listings, search results and social media alongside your title — often before anybody opens the paper. Journals ask for it to make their content findable and comprehensible at a glance.\n\nFor you the practical consequence is that a non-compliant file is rejected at upload, which delays the submission for a reason that has nothing to do with the research."}},{"@type":"Question","name":"What is the difference between a graphical abstract and an infographic?","acceptedAnswer":{"@type":"Answer","text":"A graphical abstract carries the conclusion and key finding of one paper in an image with minimal text. An infographic tells a broader narrative and carries substantially more text.\n\nThe practical test is text volume. If a reader has to read it rather than look at it, it has become an infographic — which is a legitimate thing to want, but not what the journal is asking for."}},{"@type":"Question","name":"What is the rough sketch for?","acceptedAnswer":{"@type":"Answer","text":"It tells us the layout and emphasis you have in mind, so the first draft lands close to your intention rather than to our reading of the paper alone.\n\nIt also shortens the job by about two working days. A photograph of a whiteboard, or anything drawn on paper, is entirely sufficient — it is not meant to be good."}},{"@type":"Question","name":"Do I own the finished graphic?","acceptedAnswer":{"@type":"Answer","text":"Yes, completely. Full copyright transfers on delivery, and for 3D you own the individual vector elements as well as the final image.\n\nThat means you can reuse it in presentations, posters, teaching material, social media and future papers without asking us or anybody else. It also means we do not use any element we cannot transfer to you."}},{"@type":"Question","name":"How much does it cost?","acceptedAnswer":{"@type":"Answer","text":"$150 for a 2D graphical abstract and $250 for 3D. Those are the published prices, and they include the concept, the draft, your revisions and every file format the journal requires.\n\nThere is no scoping call before you find out the number, and no revision that turns into an additional charge."}},{"@type":"Question","name":"Which should I choose, 2D or 3D?","acceptedAnswer":{"@type":"Answer","text":"2D for a process, a relationship, a workflow or a comparison — which is most papers. 3D for anatomical structures, molecular arrangements and spatial relationships, where flattening the image would lose the point.\n\nSend the manuscript and we will say which we think it needs, including when the answer is the cheaper one."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Research impact","item":"https://pubrica.com/services/research-impact/graphical-abstract/"}]}];

